sp_widget.client_script:
api.controller = function($scope, spUtil) {
  var c = this;

  c.Free = function(subscriptionType) {
    c.server.get({ subscription: subscriptionType }).then(function(res) {
      var isUpdated = res.data.updated; // ✅ matches server-side key

      if (isUpdated) {
        spUtil.addInfoMessage("Plan Updated Successfully!");
      } else {
        spUtil.addInfoMessage("You already have this plan!");
      }
    });
  };
};

sp_widget.css:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Inter", sans-serif;
  background-color: #0e0e0e;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 50px 20px;
  color: #000;
}

.container {
  max-width: 1200px;
  text-align: center;
}

h1 {
  font-size: 2rem;
  margin-bottom: 40px;
  color:black;
}

.plans {
  display: flex;
  justify-content: center;
  align-items: flex-start;
  gap: 25px;
  flex-wrap: nowrap; /* keeps all 3 cards side by side */
  margin: 0 auto;
  max-width: 1000px;
}

.card {
  background-color: #ffffff;
  border: 2px solid #000000;
  border-radius: 15px;
  padding: 25px;
  text-align: left;
  color: #000000;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  width: 250px; /* reduced width to fit 3 cards in one row */
  min-height: 380px;
  transition: transform 0.2s ease, box-shadow 0.3s ease;
}

.card:hover {
  transform: translateY(-5px);
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
}

.card h4 {
  font-size: 1.3rem;
  margin-bottom: 10px;
}

.price {
  font-size: 1.4rem;
  font-weight: 600;
  margin-bottom: 5px;
}

.price span {
  font-size: 0.8rem;
  color: #555;
  display: block;
  margin-top: 3px;
}

ul {
  list-style: none;
  font-size: 0.9rem;
  margin-bottom: 10px;
  color: #000000;
}

ul li {
  margin: 8px 0;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size:11px;
}

ul li::before {
  content: "★";
  color: #000000;
  font-size: 0.8rem;
}

button {
  background-color: #000000;
  color: #ffffff;
  border: none;
  border-radius: 25px;
  padding: 10px;
  font-weight: 600;
  cursor: pointer;
  margin-top: 15px;
  transition: background-color 0.3s ease;
}

button:hover {
  background-color: #333333;
}

sp_widget.script:
(function() {
  var subscription = input && input.subscription ? input.subscription : null;
  data.updated = false;
  if (subscription) {
    var user = new GlideRecord("sys_user");
    user.addQuery("sys_id", gs.getUserID());
    user.query();

    if (user.next()) {
      var username = user.user_name.toString();

      var gr = new GlideRecord("x_1811084_diya_c_0_customer_profile");
      gr.addQuery("user_id", username);
      gr.query();

      if (gr.next()) {
        var currentSub = gr.getValue("subscription");
        data.sub = currentSub;

        if (currentSub !== subscription) {
          gr.setValue("subscription", subscription);
          gr.update();
          data.updated = true;
        }
      } 
    }
  }
})();
